package com.yigongbao.backup.restore;
import org.junit.jupiter.api.Test; import java.nio.file.*; import java.util.*; import java.util.zip.*; import static org.assertj.core.api.Assertions.*;
class LocalOrderRestoreServiceTest { @Test void commitOnlyAfterAllAssets(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("a.txt"));o.write(1);o.closeEntry();o.putNextEntry(new ZipEntry("b.txt"));o.write(2);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("a.txt","b.txt"));}public void upload(Session s,String n,java.io.InputStream i){calls.add("u"+n);}public void commit(Session s){calls.add("c");}public void abort(Session s){calls.add("a");}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o")).doesNotThrowAnyException(); assertThat(calls).containsExactly("ua.txt","ub.txt","c"); }
 @Test void mapsPackagedAssetNameBackToManifestIdentity(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("42-report.pdf"));o.write(1);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("42"));}public void upload(Session s,String n,java.io.InputStream i){calls.add(n);}public void commit(Session s){}public void abort(Session s){}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o")).doesNotThrowAnyException(); assertThat(calls).containsExactly("42"); }
 @Test void unknownCommitDoesNotAbortRemoteSession(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("a.txt"));o.write(1);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("a.txt"));}public void upload(Session s,String n,java.io.InputStream i){calls.add("u"+n);}public void commit(Session s){calls.add("c");throw new CommitOutcomeUnknownException("s",new RuntimeException("timeout"));}public void abort(Session s){calls.add("a");}}; assertThatThrownBy(()->new LocalOrderRestoreService(c).restore(z,"o")).isInstanceOf(CommitOutcomeUnknownException.class); assertThat(calls).containsExactly("ua.txt","c"); }
}
